// Wraps tronweb's own browser build (dist/TronWeb.js, used as published,
// not rebundled) into Resources/Browser/vendor/tronweb.js: evaluated on
// first use by providers/tron.js, the same way sui-sdk.js is.
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const output = join(here, '../../Resources/Browser/vendor/tronweb.js');
const dist = join(here, 'node_modules/tronweb/dist');

const tronweb = JSON.parse(readFileSync(join(here, 'node_modules/tronweb/package.json'), 'utf8'));
const source = readFileSync(join(dist, 'TronWeb.js'));
const sha256 = createHash('sha256').update(source).digest('hex');

// Drop webpack's `/*! For license information ... */` pointer (the notices
// are inlined into the header below instead) and the `sourceMappingURL`
// comment (the map isn't bundled); keep the code itself byte for byte.
const bundle = source
    .toString('utf8')
    .split('\n')
    .filter((line) => !/^\/\*! For license information please see /.test(line))
    .filter((line) => !/^\/\/# sourceMappingURL=/.test(line))
    .join('\n')
    .trim();

if (bundle.includes('\n')) {
    throw new Error('dist/TronWeb.js no longer has the expected one-line layout; check the output by hand.');
}

const notices = readFileSync(join(dist, 'TronWeb.js.LICENSE.txt'), 'utf8')
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => `//   ${line.replace(/^\/\*!\s*/, '').replace(/\s*\*\/$/, '')}`);

const marker = `tronweb@${tronweb.version} dist/TronWeb.js`;

writeFileSync(output, `// vendor/tronweb.js — GENERATED by Scripts/tronweb (npm ci && npm run build),
// don't edit. TronWeb ${tronweb.version} browser build, npm \`tronweb@${tronweb.version}\`
// \`dist/TronWeb.js\` (sha256
// ${sha256}), inside a
// wrapper so it neither runs on page load nor touches page globals:
// providers/tron.js calls \`window.__reefrLoadTronWeb()\` the first time a page
// reads \`window.tronWeb\`, and gets the module (\`{TronWeb, providers, utils, ...}\`).
//
// TronWeb — ${tronweb.license} License, Copyright (c) TRON Foundation
// (https://github.com/tronprotocol/tronweb/blob/master/LICENSE). Bundled
// third-party notices from dist/TronWeb.js.LICENSE.txt:
${notices.join('\n')}
(function () {
    if (window.__reefrLoadTronWeb) {
        return;
    }

    var loaded = null;

    function load() {
        if (loaded) {
            return loaded;
        }

        // The UMD header picks its CommonJS \`exports.TronWeb = ...\` branch
        // with these locals, keeping it off \`window\`/\`define\`.
        var exports = {};
        var module;
        var define;
        var self = window;

// ---- BEGIN ${marker} ----
${bundle}

// ---- END ${marker} ----

        loaded = exports.TronWeb;
        return loaded;
    }

    Object.defineProperty(window, '__reefrLoadTronWeb', {
        value: load,
        writable: false,
        configurable: false,
        enumerable: false,
    });
})();
`);
